il_observations","pdc_rft_transport_action_receipts_412","pdc_uid632_containment_receipts_477","pdc_uid632_header_only_receipts_482","pdc_vehicle_salesperson_assignment_history_386","vehicle_master_history","vehicle_parts_updates","vehicle_work_items","vehicle_workshop_line_adjustments","pdc_authenticated_email_operation_lines","pdc_uid632_operation_completeness_receipts_479","pdc_vehicle_salesperson_assignment_receipts_386","pdc_jobcard_attachment_import_receipts","ai_email_attachments","pdc_ai_intake_proposals","pdc_authenticated_email_import_receipts","ai_email_intake","navision_backend_records","vehicles"]$order$::jsonb) WITH ORDINALITY o(table_name,ord) WHERE e.table_name=o.table_name;
