DO $disable$ DECLARE r record;BEGIN FOR r IN SELECT table_name FROM pdc483_expected WHERE table_name=ANY(ARRAY['ai_email_intake','audit_events','navision_backend_records','navision_board_activations','pdc_ai_intake_proposals','pdc_authenticated_email_import_receipts','pdc_authenticated_email_operation_lines','pdc_email_attachment_batch_receipts_323','pdc_email_attachment_batch_superseded_325','pdc_email_source_claims','pdc_jobcard_attachment_import_receipts','pdc_jobcard_attachment_rule_receipts_279','pdc_jobcard_attachment_source_row_receipts','pdc_parts_order_receipts_377','pdc_parts_stoppage_receipts_376','pdc_provider_email_observations','pdc_rft_transport_action_receipts_412','pdc_vehicle_salesperson_assignment_history_386','pdc_vehicle_salesperson_assignment_receipts_386','vehicle_parts_updates','vehicle_work_items','vehicle_workshop_line_adjustments','vehicles']) ORDER BY delete_order LOOP EXECUTE format('alter table public.%I disable trigger user',r.table_name);END LOOP;END $disable$;
DO $delete$ DECLARE r record;n bigint;BEGIN FOR r IN SELECT table_name,expected_count FROM pdc483_expected ORDER BY delete_order LOOP EXECUTE format('delete from public.%I t where exists(select 1 from pdc483_tokens x where position(x.token in to_jsonb(t)::text)>0)',r.table_name);GET DIAGNOSTICS n=ROW_COUNT;IF n<>r.expected_count THEN RAISE EXCEPTION 'PDC_483_DELETE_COUNT_MISMATCH:% expected % got %',r.table_name,r.expected_count,n USING errcode='55000';END IF;INSERT INTO pdc483_deleted VALUES(r.table_name,n);END LOOP;END $delete$;
